package pe.edu.utec.labreserve.controller;
import jakarta.validation.Valid; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import pe.edu.utec.labreserve.config.UserPrincipal; import pe.edu.utec.labreserve.dto.request.CreateProductRequestDto; import pe.edu.utec.labreserve.dto.response.*; import pe.edu.utec.labreserve.service.ProductService; import java.math.BigDecimal;
@RestController public class ProductController{private final ProductService service; public ProductController(ProductService service){this.service=service;} @PostMapping("/stores/{storeId}/products") public ResponseEntity<ProductResponseDto> publish(@PathVariable Long storeId,@Valid @RequestBody CreateProductRequestDto r,@AuthenticationPrincipal UserPrincipal user){return ResponseEntity.status(201).body(service.publish(storeId,r,user));} @GetMapping("/products") public PagedResponseDto<PublicProductResponseDto> list(@RequestParam(required=false) Long storeId,@RequestParam(required=false) BigDecimal maxPrice,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="10") int size){return service.list(storeId,maxPrice,page,size);}}
